# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">REFERANS FONKSİYON f(x) = x VE MUTLAK DEĞER n(x) = ±|x| GRAFİKLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n  <line x1="45" y1="145" x2="320" y2="145" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="182" y1="55" x2="182" y2="230" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="112" y1="215" x2="252" y2="75" stroke="#94a3b8" stroke-width="2" stroke-dasharray="5,4"/>\n  <polyline points="112,75 182,145 252,75" fill="none" stroke="#2563eb" stroke-width="3"/>\n  <polyline points="112,215 182,145 252,215" fill="none" stroke="#dc2626" stroke-width="2.5"/>\n  <circle cx="182" cy="145" r="4.5" fill="#0f172a"/>\n  <text x="265" y="75" font-size="11" font-weight="bold" fill="#2563eb">n(x) = |x|</text>\n  <text x="265" y="218" font-size="11" font-weight="bold" fill="#dc2626">k(x) = -|x|</text>\n  <text x="195" y="160" font-size="10.5" font-weight="bold" fill="#0f172a">T(0, 0)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">DOĞRUSAL FONKSİYONDAN ANALOJİ (9.2.2.a)</text>\n  <text x="377" y="95" font-size="11" fill="#1e3a8a">• f(x) = x grafiğinin x ekseni altında kalan negatif</text>\n  <text x="385" y="111" font-size="11" fill="#1e3a8a">kısmının (x &lt; 0) x eksenine göre simetriği alındığında</text>\n  <text x="385" y="127" font-size="11" font-weight="bold" fill="#1d4ed8">n(x) = |x| ("V" şekilli grafik) elde edilir.</text>\n  <text x="377" y="152" font-size="11" fill="#1e3a8a">• Tepe (Köşe) Noktası: T(0, 0) · Simetri Ekseni: x = 0</text>\n  <text x="377" y="176" font-size="11" fill="#1e3a8a">• n(x) = |x| için Tanım Kümesi: ℝ, Görüntü Kümesi: [0, ∞)</text>\n  <text x="377" y="200" font-size="11" fill="#1e3a8a">• (-∞, 0] aralığında azalan, [0, ∞) aralığında artandır;</text>\n  <text x="385" y="216" font-size="11" font-weight="bold" fill="#b91c1c">gerçek sayılarda bire bir DEĞİLDİR (n(-2) = n(2) = 2).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GENEL MUTLAK DEĞER FONKSİYONU m(x) = ±|ax + b| + c VE NİTEL ÖZELLİKLERİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TEPE NOKTASI VE SİMETRİ EKSENİ (9.2.2.b)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#14532d">• Mutlak değerin içini sıfır yapan apsis (r):</text>\n  <text x="52" y="114" font-size="11" font-weight="bold" fill="#15803d">ax + b = 0  ⇒  r = -b / a</text>\n  <text x="42" y="140" font-size="11.5" font-weight="bold" fill="#14532d">• Tepe (Köşe) Noktası: T(r, c) = T(-b/a, c)</text>\n  <text x="42" y="166" font-size="11.5" font-weight="bold" fill="#14532d">• Simetri Ekseni Doğrusu: x = -b / a</text>\n  <text x="42" y="192" font-size="11" fill="#14532d">• Kolların Yönü: Mutlak değerin önündeki işaret "+"</text>\n  <text x="52" y="208" font-size="11" fill="#14532d">ise kollar YUKARI (V); "-" ise AŞAĞI (ters Λ) bakar.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">GÖRÜNTÜ KÜMESİ, MAKS-MİN VE ARTANLIK</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#713f12">1) m(x) = +|ax + b| + c (Kollar Yukarı — "V"):</text>\n  <text x="385" y="113" font-size="10.5" fill="#713f12">• Görüntü Kümesi: [c, ∞) · Minimum değer = c</text>\n  <text x="385" y="129" font-size="10.5" fill="#713f12">• (-∞, r] aralığında AZALAN, [r, ∞) aralığında ARTAN.</text>\n  <text x="377" y="156" font-size="11" font-weight="bold" fill="#713f12">2) m(x) = -|ax + b| + c (Kollar Aşağı — "Λ"):</text>\n  <text x="385" y="173" font-size="10.5" fill="#713f12">• Görüntü Kümesi: (-∞, c] · Maksimum değer = c</text>\n  <text x="385" y="189" font-size="10.5" fill="#713f12">• (-∞, r] aralığında ARTAN, [r, ∞) aralığında AZALAN.</text>\n  <text x="377" y="216" font-size="10.5" font-weight="bold" fill="#854d0e">Sağ kol eğimi: +|a|, Sol kol eğimi: -|a| (veya tersi)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PARÇALI FONKSİYON GÖSTERİMİ VE ÖRNEK GRAFİK: m(x) = |x - 2| - 3</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/>\n  <line x1="45" y1="135" x2="320" y2="135" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="140" y1="55" x2="140" y2="230" stroke="#64748b" stroke-width="1.5"/>\n  <line x1="190" y1="55" x2="190" y2="230" stroke="#9333ea" stroke-width="1.5" stroke-dasharray="4,4"/>\n  <polyline points="90,85 190,185 290,85" fill="none" stroke="#16a34a" stroke-width="3"/>\n  <circle cx="190" cy="185" r="4.5" fill="#dc2626"/>\n  <circle cx="115" cy="135" r="3.5" fill="#2563eb"/>\n  <circle cx="265" cy="135" r="3.5" fill="#2563eb"/>\n  <text x="195" y="202" font-size="10.5" font-weight="bold" fill="#dc2626">T(2, -3)</text>\n  <text x="102" y="150" font-size="10" font-weight="bold" fill="#2563eb">-1</text>\n  <text x="265" y="150" font-size="10" font-weight="bold" fill="#2563eb">5</text>\n  <text x="195" y="70" font-size="10" font-weight="bold" fill="#9333ea">x = 2 (Simetri Eks.)</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">PARÇALI GÖSTERİM ÇIKARIMI (9.2.2.c)</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#581c87">Kritik Nokta (Tepe Apsisi): x - 2 = 0 ⇒ x = 2</text>\n  <text x="377" y="122" font-size="11" fill="#4c1d95">• x ≥ 2 için iç kısım (+) olduğundan aynen çıkar:</text>\n  <text x="390" y="140" font-size="11.5" font-weight="bold" fill="#16a34a">m(x) = (x - 2) - 3 = x - 5   (x ≥ 2)</text>\n  <text x="377" y="166" font-size="11" fill="#4c1d95">• x &lt; 2 için iç kısım (-) olduğundan "-" ile çarpılır:</text>\n  <text x="390" y="184" font-size="11.5" font-weight="bold" fill="#dc2626">m(x) = -(x - 2) - 3 = -x - 1   (x &lt; 2)</text>\n  <text x="377" y="212" font-size="10.5" font-weight="bold" fill="#6b21a8">Sıfırları (Kökleri): |x - 2| - 3 = 0 ⇒ x₁ = 5 ve x₂ = -1</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
